INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 11, 'theory', 'Quiz: vCPUs, NUMA, Pinning, and Steal Time');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 0, 'What does steal time show the guest?', '["The time when the vCPU was ready to run but the host gave it no physical core", "Disk idle time", "Network delay time", "Guest boot time"]', 0, 'A consistently high value is a sign of an overloaded host or a noisy neighbor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 1, 'How does a quota (cpu.max) differ from a weight (cpu.weight)?', '["A weight limits always, and a quota only under contention", "They are the same", "A quota limits consumption always, while a weight splits a core proportionally only under contention", "A weight sets the set of cores"]', 2, 'Exceeding the quota leads to forced pauses, called throttling.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 2, 'Why aren''t sibling threads of one core (SMT) given to different untrusted machines?', '["It is forbidden in the BIOS", "They share the core''s resources and caches: this causes contention and side channels", "It breaks NUMA", "It increases the disk size"]', 1, 'vCPU pinning usually takes into account pairs of logical processors of the same physical core.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 3, 'Why does NUMA matter for a virtual machine?', '["NUMA speeds up disks", "NUMA is only needed for networking", "NUMA enables hyper-threading", "Accessing a remote node''s memory goes through the inter-socket link and costs more, so a machine''s vCPUs and memory are kept on the same node"]', 3, 'For large machines, the guest is shown a virtual NUMA topology.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 11, 4, 'What is the price of polling before a vCPU halts (halt polling)?', '["CPU time: polling speeds up wake-up but burns CPU", "Memory", "Disk", "Network"]', 0, 'If the interrupt arrives soon, wake-up is instant; if not, the polling is wasted.');
